#pragma once

// The third-party software and assets in the apps (src/host/data/credits.tsv, generated by
// tools/gen/credits.mjs), for their About dialogs. The web app reads the same file; the website's
// Credits page (docs/credits.md) is generated from the same source.

#include <string>
#include <string_view>
#include <vector>

namespace dd::host {

/// One credited component.
struct Credit {
  std::string name;               ///< `miniz`
  std::string version;            ///< `3.0.2`, or how the version is chosen (`system`)
  std::string license;            ///< `MIT`: an SPDX expression where there is one
  std::string url;                ///< its home page
  std::vector<std::string> apps;  ///< the apps that ship it: `gtk`, `macos`, `winui`, `web`, `desktop`
  bool operator==(const Credit&) const = default;
};

/// Reads credits in the file's format: name, version, licence, address and the apps (separated by
/// spaces), separated by tabs, one per line, with `//` comment lines. Fields lose ASCII blanks at
/// either end. Lines without a name and those with fewer than five fields are left out.
[[nodiscard]] std::vector<Credit> parse_credits(std::string_view text);

/// The credits of one app (`gtk`, `macos` or `winui`), in the file's order (by name).
[[nodiscard]] std::vector<Credit> credits_for(std::string_view app);

/// `miniz 3.0.2 (MIT)`: a credit as one line of text.
[[nodiscard]] std::string credit_label(const Credit& credit);

}  // namespace dd::host
